import json,os,hashlib,shutil
W='/scratch/jjyeung/orch_n30/tree_rebuild10_w'; Z=W+'/w24z10/out'; S=W+'/work/s24m4z10e3'
d=json.load(open(Z+'/UPLOADS_24M4Z10_E3.json')); names=[l.strip() for l in open(Z+'/UPLOADS_24M4Z10_E3.list') if l.strip()]
out={}
def walk(x):
    if isinstance(x,dict):
        n=x.get('name') or x.get('destination') or x.get('opaque_name'); p=x.get('local_path') or x.get('source') or x.get('path')
        if n and p and 'sha256' in x: out[n]=x; return
        for v in x.values(): walk(v)
    elif isinstance(x,list):
        for v in x: walk(v)
walk(d); print('json entries',len(out),'list',len(names)); miss=[n for n in names if n not in out]; print('missing',miss)
assert not miss
sums=[]
for n in names:
    x=out[n]; p=x.get('local_path') or x.get('source') or x.get('path'); assert not n.startswith('/') and '..' not in n.split('/')
    h=hashlib.sha256(open(p,'rb').read()).hexdigest(); assert h==x['sha256'],n
    dst=os.path.join(S,n); os.makedirs(os.path.dirname(dst),exist_ok=True); shutil.copyfile(p,dst); sums.append('%s  %s'%(h,n))
open(S+'/MANIFEST.sha','w').write('\n'.join(sums)+'\n'); print('ok',len(sums))
PY
